1	/**
2	 * The Angular holdout: compose the `@versionless/angular` changeset for the
3	 * pinned `angular-pigallery2-v1-7-0` tree and write it into a migrated lane, so
4	 * a closure can be installed into it and a production build attempted on the
5	 * bytes the frozen adapter produced.
6	 *
7	 * This application was never seen by the adapter while the adapter was being
8	 * designed. Nothing in `@versionless/angular` was written for it, and nothing in
9	 * `@versionless/angular` was changed for it: the adapter subtree is frozen at
10	 * tree oid ca3824d0595d1fa88d37feda6b1785dfd79e72c4 for the whole of this unit.
11	 * What this driver produces is therefore a measurement and not a demonstration.
12	 *
13	 * The driver is fixture-scoped. It knows three things about this application —
14	 * where its corpus was materialised, that its Angular `sourceRoot` is
15	 * `frontend/` rather than the conventional `src/`, and that the browser build's
16	 * compilation unit reaches into the sibling `common/` directory the backend also
17	 * compiles. Those are paths, read out of the application's own `angular.json`
18	 * and `tsconfig.app.json`. Every decision about *what to change* lives in the
19	 * frozen adapter, which knows nothing about this application.
20	 */
21	
22	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
23	import * as path from 'pathe';
24	import {
25		migrateAngularCliEraWorkspace,
26		readMissingMembers,
27		ANGULAR_16_BROWSER_CELL,
28		type AngularMigration,
29		type DeepImportReading,
30		type MissingMemberDiagnosticReading,
31		type WorkspaceFile,
32	} from '../../../frameworks/angular/src/index.ts';
33	import { readDeepImportReading } from './angular-tiny-translator-final-run.ts';
34	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
35	import { sealRecord, verifySealedRecord, type SealedRecord } from './angular-factoriolab-build-lanes-run.ts';
36	import { applyMigration, type Application } from './angular-tiny-translator-apply-run.ts';
37	
38	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
39	
40	export const UNIT = 'lrapr-t018/u3-frozen-adapter-migration';
41	export const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
42	export const COMMIT = '6d44c22df13b8f9416715e86e160707d0c3f973a';
43	
44	/** The immutable corpus the baseline lane was also cut from. */
45	export const SOURCE_TREE = path.join(
46		repositoryRoot,
47		'.versionless/cache/angular-pigallery2-v1-7-0-source/corpus',
48		`pigallery2-${COMMIT}`,
49	);
50	
51	/** The era lane: the pinned revision with the era closure installed into it. */
52	export const ERA_CLOSURE_TREE = path.join(
53		repositoryRoot,
54		'.versionless/work/angular-pigallery2/baseline',
55	);
56	
57	/** The migrated lane, beside the baseline lane the previous unit built. */
58	export const STAGE_DIRECTORY = path.join(repositoryRoot, '.versionless/work/angular-pigallery2/target');
59	/** The pinned revision with the changeset written into it; the build tree. */
60	export const APPLIED_TREE = path.join(STAGE_DIRECTORY, 'app');
61	
62	export const EVIDENCE_DIRECTORY = path.join(
63		repositoryRoot,
64		'evidence/ingests/angular-pigallery2-v1-7-0/migration',
65	);
66	
67	export const CHANGESET_FILE = 'u3-composed-changeset.json';
68	export const MIGRATION_RECORD_FILE = 'u3-source-migration.json';
69	
70	/**
71	 * The two directories the Angular browser build compiles, and why the second one
72	 * is not the conventional single `sourceRoot`.
73	 *
74	 * `angular.json` declares `sourceRoot: "frontend"`, and `frontend/tsconfig.app.json`
75	 * includes `./**\/*` relative to it. TypeScript then follows the relative imports
76	 * the frontend modules write into `../common/`, so `common/**\/*.ts` is inside the
77	 * browser build's compilation unit even though no configuration file names it.
78	 * A migration handed only `frontend/` would scan a strict subset of what the
79	 * compiler reads.
80	 */
81	export const APPLICATION_SOURCE_DIRECTORIES: readonly string[] = Object.freeze(['frontend', 'common']);
82	
83	/**
84	 * The build log the previous migrated run wrote, and which this one reads.
85	 *
86	 * Two capabilities in the adapter are positioned by the compiler's own
87	 * coordinates rather than by a shape in the source, because what they answer is
88	 * not visible in the source: a member the target line's `lib.dom.d.ts` stopped
89	 * declaring reads exactly as it always did. A caller that has never compiled the
90	 * tree supplies no such reading and gets no such transform, which is the seam
91	 * `unparameterised-base-class` already had. This driver has compiled the tree —
92	 * the log is in this application's own evidence directory — so it reads it.
93	 */
94	export const PREVIOUS_BUILD_LOG = 't021-u3-lane-build-run1.log';
95	
96	/** The package this application reaches past the published surface of. */
97	export const DEEP_IMPORT_PACKAGES: readonly string[] = Object.freeze(['ngx-bootstrap']);
98	
99	/**
100	 * The `@types/` packages the era closure carried, by name.
101	 *
102	 * An era application can import a package directly and declare neither it nor
103	 * its type companion, because something else in the closure installed both. The
104	 * migrated closure has neither, and which companions the era one had is a fact
105	 * about that installation rather than about any package name — so it is read off
106	 * the era lane rather than inferred.
107	 */
108	export async function readEraClosureTypePackages(tree: string): Promise<readonly string[]> {
109		const directory = path.join(tree, 'node_modules', '@types');
110		try {
111			const entries = await readdir(directory, { withFileTypes: true });
112			return Object.freeze(
113				entries
114					.filter((entry) => entry.isDirectory() || entry.isSymbolicLink())
115					.map((entry) => `@types/${entry.name}`)
116					.sort(),
117			);
118		} catch {
119			return Object.freeze([]);
120		}
121	}
122	
123	/** The `TS2339` positions the previous migrated build reported, per module. */
124	export async function readMissingMemberDiagnostics(
125		log: string,
126	): Promise<readonly MissingMemberDiagnosticReading[]> {
127		const source = await readFile(path.join(EVIDENCE_DIRECTORY, log), 'utf8');
128		return Object.freeze(
129			[...readMissingMembers(source)]
130				.map(([modulePath, diagnostics]) => Object.freeze({ path: modulePath, diagnostics }))
131				.sort((left, right) => (left.path < right.path ? -1 : 1)),
132		);
133	}
134	
135	/** What the packages this application deep-imports actually publish. */
136	export async function readDeepImportReadings(tree: string): Promise<readonly DeepImportReading[]> {
137		const readings: DeepImportReading[] = [];
138		for (const name of DEEP_IMPORT_PACKAGES) readings.push(await readDeepImportReading(tree, name));
139		return Object.freeze(readings);
140	}
141	
142	async function filesBelow(
143		directory: string,
144		root: string,
145		extension: string,
146	): Promise<WorkspaceFile[]> {
147		const files: WorkspaceFile[] = [];
148		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
149			left.name < right.name ? -1 : 1,
150		)) {
151			const item = path.join(directory, entry.name);
152			if (entry.isDirectory()) {
153				files.push(...(await filesBelow(item, root, extension)));
154				continue;
155			}
156			if (!entry.isFile() || path.extname(entry.name) !== extension) continue;
157			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
158		}
159		return files;
160	}
161	
162	/** Every workspace-relative path the tree carries, excluding installed packages. */
163	async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
164		const paths: string[] = [];
165		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
166			left.name < right.name ? -1 : 1,
167		)) {
168			if (entry.name === 'node_modules' || entry.name === '.git') continue;
169			const item = path.join(directory, entry.name);
170			if (entry.isDirectory()) {
171				paths.push(...(await workspacePathsBelow(item, root)));
172				continue;
173			}
174			if (entry.isFile()) paths.push(path.relative(root, item));
175		}
176		return paths;
177	}
178	
179	async function collect(
180		tree: string,
181		extension: string,
182		directories: readonly string[],
183	): Promise<WorkspaceFile[]> {
184		const files: WorkspaceFile[] = [];
185		for (const directory of directories)
186			files.push(...(await filesBelow(path.join(tree, directory), tree, extension)));
187		return files;
188	}
189	
190	/**
191	 * Compose the changeset for the pinned tree.
192	 *
193	 * The workspace configuration handed in is a modern `angular.json`, so the
194	 * CLI 1.x synthesis capability stands down on its own — it reads the document's
195	 * shape, and nothing here tells it which format to expect.
196	 */
197	export async function composeMigration(tree: string): Promise<AngularMigration> {
198		const sourceModules = (await collect(tree, '.ts', APPLICATION_SOURCE_DIRECTORIES)).filter(
199			(module) => !module.path.endsWith('.spec.ts'),
200		);
201		return migrateAngularCliEraWorkspace(
202			{
203				missingMemberDiagnostics: await readMissingMemberDiagnostics(PREVIOUS_BUILD_LOG),
204				deepImportReadings: await readDeepImportReadings(APPLIED_TREE),
205				eraClosureTypePackages: await readEraClosureTypePackages(ERA_CLOSURE_TREE),
206				packageManifest: {
207					path: 'package.json',
208					source: await readFile(path.join(tree, 'package.json'), 'utf8'),
209				},
210				workspaceConfig: {
211					path: 'angular.json',
212					source: await readFile(path.join(tree, 'angular.json'), 'utf8'),
213				},
214				tsConfig: {
215					path: 'tsconfig.json',
216					source: await readFile(path.join(tree, 'tsconfig.json'), 'utf8'),
217				},
218				sourceModules,
219				templates: await collect(tree, '.html', ['frontend']),
220				styleSheets: await collect(tree, '.css', ['frontend']),
221				workspaceFiles: await workspacePathsBelow(tree, tree),
222			},
223			ANGULAR_16_BROWSER_CELL,
224		);
225	}
226	
227	/**
228	 * Era workspace facts this application carries that the hop has to answer for or
229	 * declare dropped. They are named because a changeset that silently loses one of
230	 * them would still look clean.
231	 */
232	export const ERA_WORKSPACE_FACTS: readonly string[] = Object.freeze([
233		'`sourceRoot: "frontend"` and an `outputPath` of `dist` at the workspace root — this workspace is not `src/`-rooted, and its build output directory is the same one the backend release pipeline writes into.',
234		'`extractCss: true` on the production configuration — a valid key for the Angular 8 browser builder, and one the Angular 13 line removed.',
235		"The build is driven by the repository's own gulp task rather than by `ng` directly, and that task passes `--i18n-locale en --i18n-format=xlf --i18n-file=frontend/translate/messages.en.xlf --i18n-missing-translation warning`. Those are ViewEngine i18n flags of the Angular 8 CLI; the workspace file itself declares no i18n at all.",
236		'A second workspace project, pigallery2-e2e, whose only targets are the protractor e2e runner and a TSLint lint target.',
237		'The pigallery2 lint target names `src/tsconfig.app.json` and `src/tsconfig.spec.json` — paths that do not exist in this tree, because the workspace was renamed to `frontend/` without updating them. The era lint target was already broken at the pin.',
238		'`@angular/http@7.2.15` declared beside Angular 8.1.2 — a package Angular removed after the 7 line.',
239		'`rxjs-compat@6.5.2`, the RxJS 5-compatibility shim, declared beside rxjs 6.5.2.',
240	]);
241	
242	/** The changeset record: every file by path and by digest before and after. */
243	export function buildChangesetRecord(migration: AngularMigration): SealedRecord {
244		return sealRecord({
245			schemaVersion: 'versionless.angular-pigallery2-composed-changeset.v1',
246			unit: UNIT,
247			consentId: CONSENT,
248			cell: migration.cell,
249			appliedTo: `The pinned revision ${COMMIT} as materialised, read-only, at .versionless/cache/angular-pigallery2-v1-7-0-source/corpus — the same corpus the era baseline lane was cut from.`,
250			holdoutPosition:
251				'The Angular holdout. This application was never ingested, fixtured, adapted, witnessed or receipted in this repository before T018, and the adapter subtree was frozen before this unit began. No capability was written for it and none was changed for it; the changeset is what the existing inventory produced when it was pointed at a tree it had never seen.',
252			eraWorkspaceFacts: ERA_WORKSPACE_FACTS,
253			applicationSourceDirectories: APPLICATION_SOURCE_DIRECTORIES,
254			applicationFilesScanned: migration.applicationFilesScanned,
255			applicationFilesChanged: migration.applicationFilesChanged,
256			workspaceFilesChanged: migration.workspaceFilesChanged,
257			files: migration.files.map((entry) => ({
258				path: entry.path,
259				kind: entry.kind,
260				changed: entry.changed,
261				sha256Before: entry.sha256Before,
262				sha256After: entry.sha256After,
263				changes: entry.changes,
264			})),
265			removedFiles: migration.removedFiles,
266			declaredDifferences: migration.declaredDifferences,
267			unhandled: migration.unhandled,
268			notEstablished: [
269				'A composed changeset is a set of edits, not a build. Nothing here establishes that the migrated tree installs, compiles or emits anything.',
270				'`applicationFilesChanged` counts application source a transform rewrote. A file the adapter scanned and left alone is counted as scanned and not as changed.',
271				'A cell disposition is a reading of a registry, not an installation. A range written here has not been resolved against a lockfile by this record.',
272			],
273		});
274	}
275	
276	/** The applied-changeset record: the same changeset, written into a named tree. */
277	export function buildApplicationRecord(
278		migration: AngularMigration,
279		applied: Application,
280	): SealedRecord {
281		return sealRecord({
282			schemaVersion: 'versionless.angular-pigallery2-source-migration.v1',
283			unit: UNIT,
284			consentId: CONSENT,
285			cell: migration.cell,
286			appliedTo: {
287				tree: '.versionless/work/angular-pigallery2/target/app',
288				from: `.versionless/cache/angular-pigallery2-v1-7-0-source/corpus/pigallery2-${COMMIT}`,
289				commit: COMMIT,
290				excludedFromStage: ['node_modules', '.git'],
291				excludedReason:
292					'The corpus carries neither: it is the extracted release tarball, verified blob for blob against the pinned git tree by the ingest unit.',
293			},
294			applicationFilesScanned: migration.applicationFilesScanned,
295			applicationFilesChanged: migration.applicationFilesChanged,
296			workspaceFilesChanged: migration.workspaceFilesChanged,
297			filesWritten: applied.written,
298			filesRemoved: applied.removed,
299			declaredDifferences: migration.declaredDifferences,
300			unhandled: migration.unhandled,
301			notEstablished: [
302				'Writing a changeset into a tree is not a build. Nothing here establishes that the applied tree installs, compiles or emits anything; the lane record beside this one states what happened when that was attempted.',
303				'No application source was edited by hand in this lane. Every byte that differs from the corpus was written by a frozen adapter transform, and each is itemised in the changeset record by file and by change.',
304			],
305		});
306	}
307	
308	export async function main(): Promise<void> {
309		const migration = await composeMigration(SOURCE_TREE);
310		const changeset = verifySealedRecord(buildChangesetRecord(migration));
311		const applied = await applyMigration(migration, APPLIED_TREE);
312		const record = verifySealedRecord(buildApplicationRecord(migration, applied));
313		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
314		await writeFile(path.join(EVIDENCE_DIRECTORY, CHANGESET_FILE), canonical(changeset));
315		await writeFile(path.join(EVIDENCE_DIRECTORY, MIGRATION_RECORD_FILE), canonical(record));
316		process.stdout.write(
317			`applied ${String(applied.written.length)} files (${String(
318				migration.applicationFilesChanged,
319			)}/${String(migration.applicationFilesScanned)} application, ${String(
320				migration.workspaceFilesChanged,
321			)} workspace), removed ${String(applied.removed.length)}, ` +
322				`${String(migration.unhandled.length)} unhandled, ${String(
323					migration.declaredDifferences.length,
324				)} declared differences; changeset digest ${sha256(canonical(changeset)).slice(0, 12)}\n`,
325		);
326	}
327	
328	if (process.argv[1]?.endsWith('angular-pigallery2-migration-run.ts'))
329		main().catch((error: unknown) => {
330			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
331			process.exitCode = 1;
332		});
