1	/**
2	 * A symbol reached through an entry point the package no longer publishes, whose
3	 * successor on the root is spelled differently.
4	 *
5	 * `TS2307: Cannot find module 'rxjs/internal-compatibility'` looks like the
6	 * unreachable-subpath shape {@link redirectUnreachableImports} answers, and it is
7	 * not. That capability moves a name between entry points of the same package,
8	 * and it can only do so because the name is still published somewhere: the
9	 * reading finds it and the import follows it. Here the entry point is gone *and*
10	 * the name is gone. `rxjs@7` publishes no `fromPromise` from anywhere, so a
11	 * collapse onto the root would import a name the package does not have and move
12	 * the failure from TS2307 to TS2305.
13	 *
14	 * The successor is therefore a written-down claim, exactly as
15	 * {@link renameDeclaredTypeMembers}'s is — someone read a release note, not a
16	 * declaration. This file states that plainly because it is the whole of the risk.
17	 * What the tree can still do is refuse the claim, and it is asked to three times
18	 * before anything is written: the removed specifier really has to be unreachable,
19	 * the root really has to publish the successor, and the root really has to *not*
20	 * publish the replaced name. A tree that still answers the specifier is a tree
21	 * where the diagnostic means something else; a root that already publishes the
22	 * old name is one where the claim describes some other release.
23	 *
24	 * The call shape is the fourth refusal and the one that keeps the claim narrow.
25	 * `fromPromise` was a single-argument creation function and `from` is an overload
26	 * set; the claim is stated for one arity, and a site that uses the symbol at any
27	 * other arity — or that does not call it at all, passing it as a value, reading a
28	 * member off it, aliasing it away — is refused with the whole declaration. Half a
29	 * rewrite is worse than none: it would leave a binding pointing at a module that
30	 * does not resolve while claiming the file was migrated.
31	 */
32	
33	import { compareStrings } from './angular-target-cell.ts';
34	import {
35		applySourceEdits,
36		forEachNode,
37		isFreeRootName,
38		lineOf,
39		parseModule,
40		type AstNode,
41		type SourceEdit,
42	} from './semantic-module.ts';
43	
44	const CAPABILITY = 'Removed entry point symbol successor';
45	
46	/**
47	 * One removed-entry-point symbol and its successor on the package root, as a
48	 * claim to be checked. `arity` is the call shape the claim is stated for, and it
49	 * is part of the claim rather than a convenience: a successor that is right for
50	 * one shape of call is not thereby right for another.
51	 */
52	export type DocumentedSymbolSuccessor = Readonly<{
53		package: string;
54		/** The specifier the application imports through, e.g. `rxjs/internal-compatibility`. */
55		specifier: string;
56		from: string;
57		to: string;
58		arity: number;
59		/** The release that made the change, for the record and the refusal messages. */
60		since: string;
61	}>;
62	
63	/**
64	 * What the installed package answers. `specifierResolves` is the reading that
65	 * makes the diagnostic this capability's business; `rootExports` is the two-sided
66	 * check on the claim.
67	 */
68	export type RootSurfaceReading = Readonly<{
69		package: string;
70		version: string;
71		specifier: string;
72		specifierResolves: boolean;
73		rootExports: readonly string[];
74		/** An incomplete reading proves no name absent, and the claim is refused on it. */
75		complete: boolean;
76	}>;
77	
78	export type SymbolSuccessorChange = Readonly<{
79		kind: 'removed-entry-point-symbol-successor';
80		line: number;
81		specifier: string;
82		root: string;
83		from: string;
84		to: string;
85		callSites: number;
86	}>;
87	
88	export type SymbolSuccessorMigration = Readonly<{
89		path: string;
90		source: string;
91		changed: boolean;
92		changes: readonly SymbolSuccessorChange[];
93		unhandled: readonly string[];
94	}>;
95	
96	/** The successors this adapter has been told about. */
97	export const DOCUMENTED_SYMBOL_SUCCESSORS: readonly DocumentedSymbolSuccessor[] = Object.freeze([
98		Object.freeze({
99			package: 'rxjs',
100			specifier: 'rxjs/internal-compatibility',
101			from: 'fromPromise',
102			to: 'from',
103			arity: 1,
104			since: 'rxjs 7',
105		}),
106	]);
107	
108	/** Every identifier node in a module that resolves to `symbol`. */
109	function referencesTo(module: ReturnType<typeof parseModule>, local: unknown): readonly AstNode[] {
110		const found: AstNode[] = [];
111		forEachNode(module.ast, (node) => {
112			if (node.type !== 'Identifier') return;
113			if (module.symbolOf(node) !== local) return;
114			found.push(node);
115		});
116		return Object.freeze(found);
117	}
118	
119	/**
120	 * Rewrite one module's imports of a removed entry point onto the package root,
121	 * where the installed root proves the successor and every use is the call shape
122	 * the claim was stated for.
123	 */
124	export function succeedRemovedEntryPointSymbols(
125		path: string,
126		source: string,
127		claims: readonly DocumentedSymbolSuccessor[],
128		readings: readonly RootSurfaceReading[],
129	): SymbolSuccessorMigration {
130		const module = parseModule(CAPABILITY, path, source);
131		const edits: SourceEdit[] = [];
132		const changes: SymbolSuccessorChange[] = [];
133		const unhandled: string[] = [];
134		for (const declaration of module.ast.body) {
135			if (declaration.type !== 'ImportDeclaration') continue;
136			const specifier: unknown = declaration.source.value;
137			if (typeof specifier !== 'string') continue;
138			const applicable = claims.filter((claim) => claim.specifier === specifier);
139			if (applicable.length === 0) continue;
140			const line = lineOf(source, declaration.start);
141			const at = `${path} line ${String(line)}`;
142			const refuse = (reason: string): void => {
143				unhandled.push(`${at}: ${reason}`);
144			};
145			const root = (applicable[0] as DocumentedSymbolSuccessor).package;
146			const reading = readings.find(
147				(entry) => entry.package === root && entry.specifier === specifier,
148			);
149			if (reading === undefined) {
150				refuse(`no root surface was read for '${root}', so ${specifier} was left as it is`);
151				continue;
152			}
153			if (!reading.complete) {
154				refuse(
155					`the root surface of '${root}'@${reading.version} is incomplete, so it establishes ` +
156						'neither that a successor is published nor that the replaced name is not',
157				);
158				continue;
159			}
160			if (reading.specifierResolves) {
161				refuse(
162					`'${root}'@${reading.version} still answers ${specifier}, so the diagnostic does not ` +
163						'describe this closure and the rewrite would be a rewrite of working code',
164				);
165				continue;
166			}
167			let wide = false;
168			const named: { name: string; localName: string; local: unknown; node: AstNode }[] = [];
169			for (const imported of declaration.specifiers) {
170				if (
171					imported.type !== 'ImportSpecifier' ||
172					imported.imported.type !== 'Identifier' ||
173					imported.local.type !== 'Identifier'
174				) {
175					wide = true;
176					continue;
177				}
178				named.push({
179					name: imported.imported.name,
180					localName: imported.local.name,
181					local: module.symbolOf(imported.local),
182					node: imported.local,
183				});
184			}
185			if (wide) {
186				refuse(
187					`${specifier} is unreachable and the declaration carries a default or namespace ` +
188						'binding, whose members cannot be resolved to a successor by name',
189				);
190				continue;
191			}
192			if (named.length === 0) {
193				refuse(
194					`${specifier} is unreachable and the declaration names no symbol — it is imported for ` +
195						'its side effect, and nothing about the published surface says which entry point runs ' +
196						'the same one',
197				);
198				continue;
199			}
200			const resolved: { claim: DocumentedSymbolSuccessor; callees: readonly AstNode[] }[] = [];
201			const refusals: string[] = [];
202			for (const entry of named) {
203				const claim = applicable.find((candidate) => candidate.from === entry.name);
204				if (claim === undefined) {
205					refusals.push(`no successor is written down for ${entry.name}`);
206					continue;
207				}
208				if (!reading.rootExports.includes(claim.to)) {
209					refusals.push(
210						`${claim.since} is said to have replaced ${claim.from} with ${claim.to}, and the root ` +
211							`of '${root}'@${reading.version} does not publish ${claim.to}`,
212					);
213					continue;
214				}
215				if (reading.rootExports.includes(claim.from)) {
216					refusals.push(
217						`the root of '${root}'@${reading.version} publishes ${claim.from}, so the name did ` +
218							'not go away and the specifier is the only thing that did',
219					);
220					continue;
221				}
222				if (entry.localName !== entry.name) {
223					refusals.push(
224						`${entry.name} is imported as ${entry.localName}, and a successor written through an ` +
225							'alias would rename the binding as well as the import',
226					);
227					continue;
228				}
229				if (!isFreeRootName(module, claim.to)) {
230					refusals.push(
231						`${claim.to} is already bound in this module's root scope, so importing the successor ` +
232							'under its own name would shadow or collide with it',
233					);
234					continue;
235				}
236				const uses = referencesTo(module, entry.local).filter((node) => node !== entry.node);
237				const callees: AstNode[] = [];
238				let bad: string | null = null;
239				for (const use of uses) {
240					const parent = module.parentOf(use);
241					if (parent === null || parent.type !== 'CallExpression' || parent.callee !== use) {
242						bad =
243							`${entry.name} is used at line ${String(lineOf(source, use.start))} other than as ` +
244							'the callee of a call, and the successor is written down as a replacement for the ' +
245							'call and not for the value';
246						break;
247					}
248					if (parent.arguments.length !== claim.arity) {
249						bad =
250							`${entry.name} is called at line ${String(lineOf(source, use.start))} with ` +
251							`${String(parent.arguments.length)} argument(s), and the successor is written down ` +
252							`for the ${String(claim.arity)}-argument form only`;
253						break;
254					}
255					callees.push(use);
256				}
257				if (bad !== null) {
258					refusals.push(bad);
259					continue;
260				}
261				resolved.push({ claim, callees: Object.freeze(callees) });
262			}
263			if (refusals.length > 0) {
264				for (const reason of refusals)
265					refuse(
266						`${specifier} is unreachable and ${reason}. The whole declaration was left as it is: ` +
267							'rewriting the symbols that do resolve would leave the ones that do not pointing at ' +
268							'a module this tree does not answer.',
269					);
270				continue;
271			}
272			const quote = source.slice(declaration.source.start, declaration.source.start + 1);
273			const inner = resolved
274				.map((entry) => entry.claim.to)
275				.sort(compareStrings)
276				.join(', ');
277			let end = declaration.end;
278			if (source[end] === ';') end += 1;
279			edits.push({ start: declaration.start, end, text: `import {${inner}} from ${quote}${root}${quote};` });
280			for (const entry of resolved) {
281				for (const callee of entry.callees)
282					edits.push({ start: callee.start, end: callee.end, text: entry.claim.to });
283				changes.push({
284					kind: 'removed-entry-point-symbol-successor',
285					line,
286					specifier,
287					root,
288					from: entry.claim.from,
289					to: entry.claim.to,
290					callSites: entry.callees.length,
291				});
292			}
293		}
294		const migrated = applySourceEdits(source, edits);
295		return Object.freeze({
296			path,
297			source: migrated,
298			changed: migrated !== source,
299			changes: Object.freeze(changes),
300			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
301		});
302	}
