1	/**
2	 * Packages the application's own source names and its manifest does not declare.
3	 *
4	 * `undeclared-runtime-dependency` beside this one reads the *closure*: what each
5	 * installed package's shipped bundles import without declaring. That reading
6	 * finds holes a library left. It cannot find the holes the application itself
7	 * left, and it cannot find the holes a migration *opens*, which is the case this
8	 * capability exists for:
9	 *
10	 * - An application imports `leaflet` directly and declares only the Angular
11	 *   wrapper around it. The era closure supplied `leaflet` transitively, so the
12	 *   import resolved; the wrapper is a package the target cell read and found no
13	 *   successor for, so after the disposition drops it the transitive edge is gone
14	 *   and a direct import in application source stops resolving. The dependency
15	 *   was always the application's, and the era manifest never said so.
16	 * - An application writes a webpack **inline loader chain** —
17	 *   `require('raw-loader!./messages.xlf')` — and the loader package came into the
18	 *   tree as a transitive dependency of the era builder. A newer builder does not
19	 *   depend on it, and the chain has no resolver.
20	 *
21	 * Both are one fact read one way: a bare package name written in application
22	 * source, resolved by nothing the manifest declares. The reading rides the
23	 * parsed module, so a specifier inside a comment or an unrelated string is not
24	 * one, and the loader half reads webpack's own syntax — every `!`-separated
25	 * segment before the module request names a loader — rather than matching a
26	 * loader name. A chain whose module request is a template literal is still read:
27	 * the loader segments are in the literal's static prefix even when the request
28	 * they precede is computed at runtime.
29	 *
30	 * ## What it will not invent
31	 *
32	 * The version. A range comes from the target cell by the same rule every other
33	 * declaration in this adapter comes from, and a package the cell has read no
34	 * line for — or has read and found no successor for — is reported by name with
35	 * every site that needs it, and nothing is written. That report is the honest
36	 * form of "this application cannot be carried to this cell without a decision",
37	 * and it is deliberately louder than a missing declaration: after the cell has
38	 * dropped a package the application still imports, the manifest saying nothing
39	 * and the source saying `import` is the whole of the remaining gap.
40	 *
41	 * ## Type declarations
42	 *
43	 * A package whose types the era closure carried as a separate `@types/` package
44	 * needs that companion declared too, or the direct import the migration just
45	 * made resolvable still does not type. Which packages those are is a reading of
46	 * the era closure — the `@types/` names it actually installed — supplied by the
47	 * caller. Nothing is inferred from a package name: a companion the era closure
48	 * did not carry is not declared, because this capability has read nothing that
49	 * says one exists.
50	 */
51	
52	import {
53		alignedVersionRange,
54		compareStrings,
55		ecosystemDispositionOf,
56		type AngularTargetCell,
57		type PackageManifest,
58	} from './angular-target-cell.ts';
59	import { forEachNode, lineOf, parseModule, type AstNode } from './semantic-module.ts';
60	import { packageNameOfSpecifier } from './undeclared-runtime-dependency.ts';
61	
62	/** One application source file, as the migration holds it. */
63	export type ApplicationModule = Readonly<{ path: string; source: string }>;
64	
65	/** How the application source named the package. */
66	export type ApplicationPackageUseKind = 'module-import' | 'inline-loader-chain';
67	
68	/** One place application source names a package. */
69	export type ApplicationPackageUse = Readonly<{
70		package: string;
71		/** The specifier exactly as written, loader segment included. */
72		specifier: string;
73		path: string;
74		line: number;
75		kind: ApplicationPackageUseKind;
76	}>;
77	
78	/** The manifest fields a declaration may already stand in. */
79	const DECLARING_FIELDS: readonly string[] = Object.freeze([
80		'dependencies',
81		'devDependencies',
82		'peerDependencies',
83		'optionalDependencies',
84	]);
85	
86	/**
87	 * The static prefix of a `require` argument: the whole string for a literal, the
88	 * first quasi for a template literal, and null for anything else. A chain's
89	 * loader segments are always inside that prefix, because webpack reads them from
90	 * the front of the request.
91	 */
92	function staticRequestPrefix(node: AstNode): string | null {
93		if (node.type === 'Literal') return typeof node.value === 'string' ? node.value : null;
94		if (node.type !== 'TemplateLiteral') return null;
95		const first = node.quasis[0];
96		if (first === undefined) return null;
97		const raw = first.value.cooked;
98		return typeof raw === 'string' ? raw : null;
99	}
100	
101	/** Whether a call is a bare `require(...)` with one argument. */
102	function requireArgument(node: AstNode): AstNode | null {
103		if (node.type !== 'CallExpression') return null;
104		if (node.callee.type !== 'Identifier' || node.callee.name !== 'require') return null;
105		const [argument] = node.arguments;
106		return argument === undefined ? null : argument;
107	}
108	
109	/**
110	 * The loader packages one webpack request names.
111	 *
112	 * Everything before the last `!` inside the static prefix is a loader chain; the
113	 * segment after it is the module request and is not a loader. Leading `!`, `!!`
114	 * and `-!` are webpack's rule-disabling markers rather than segments. A segment
115	 * carrying loader options after `?` keeps only the specifier, and a relative or
116	 * absolute loader path names no package at all.
117	 */
118	export function inlineLoaderPackages(request: string): readonly string[] {
119		let head = request;
120		while (head.startsWith('!') || head.startsWith('-!')) head = head.slice(head.startsWith('-!') ? 2 : 1);
121		const segments = head.split('!');
122		if (segments.length < 2) return Object.freeze([]);
123		const packages: string[] = [];
124		for (const segment of segments.slice(0, -1)) {
125			const query = segment.indexOf('?');
126			const specifier = query < 0 ? segment : segment.slice(0, query);
127			const name = packageNameOfSpecifier(specifier.trim());
128			if (name !== null) packages.push(name);
129		}
130		return Object.freeze(packages);
131	}
132	
133	/**
134	 * Every package application source names, from every shape this capability
135	 * reads: static imports and re-exports, and webpack inline loader chains inside
136	 * `require`.
137	 */
138	export function readApplicationPackageUses(
139		modules: readonly ApplicationModule[],
140	): readonly ApplicationPackageUse[] {
141		const uses: ApplicationPackageUse[] = [];
142		for (const module of modules) {
143			const parsed = parseModule('Application source dependency', module.path, module.source);
144			for (const record of parsed.imports) {
145				const name = packageNameOfSpecifier(record.specifier);
146				if (name === null) continue;
147				uses.push(
148					Object.freeze({
149						package: name,
150						specifier: record.specifier,
151						path: module.path,
152						line: lineOf(module.source, record.node.start),
153						kind: 'module-import' as const,
154					}),
155				);
156			}
157			for (const statement of parsed.ast.body) {
158				if (statement.type !== 'ExportAllDeclaration' && statement.type !== 'ExportNamedDeclaration')
159					continue;
160				const source = statement.source;
161				if (source === null || source === undefined || typeof source.value !== 'string') continue;
162				const name = packageNameOfSpecifier(source.value);
163				if (name === null) continue;
164				uses.push(
165					Object.freeze({
166						package: name,
167						specifier: source.value,
168						path: module.path,
169						line: lineOf(module.source, statement.start),
170						kind: 'module-import' as const,
171					}),
172				);
173			}
174			forEachNode(parsed.ast, (node) => {
175				const argument = requireArgument(node);
176				if (argument === null) return;
177				const prefix = staticRequestPrefix(argument);
178				if (prefix === null) return;
179				for (const name of inlineLoaderPackages(prefix))
180					uses.push(
181						Object.freeze({
182							package: name,
183							specifier: prefix,
184							path: module.path,
185							line: lineOf(module.source, node.start),
186							kind: 'inline-loader-chain' as const,
187						}),
188					);
189			});
190		}
191		return Object.freeze(
192			uses.sort(
193				(left, right) =>
194					compareStrings(left.package, right.package) ||
195					compareStrings(left.path, right.path) ||
196					left.line - right.line,
197			),
198		);
199	}
200	
201	export type ApplicationDependencyDeclaration = Readonly<{
202		field: 'dependencies' | 'devDependencies';
203		name: string;
204		range: string;
205		reason: string;
206	}>;
207	
208	export type ApplicationDependencyDeclarations = Readonly<{
209		manifest: PackageManifest;
210		declarations: readonly ApplicationDependencyDeclaration[];
211		declaredDifferences: readonly string[];
212		unhandled: readonly string[];
213	}>;
214	
215	/** The scoped-package spelling DefinitelyTyped publishes a companion under. */
216	export function typesCompanionOf(name: string): string {
217		if (!name.startsWith('@')) return `@types/${name}`;
218		const [scope, rest] = name.slice(1).split('/');
219		return rest === undefined ? `@types/${name}` : `@types/${scope ?? ''}__${rest}`;
220	}
221	
222	function declares(manifest: PackageManifest, name: string): boolean {
223		for (const field of DECLARING_FIELDS) {
224			const value = manifest[field];
225			if (typeof value !== 'object' || value === null || Array.isArray(value)) continue;
226			if (name in (value as Record<string, unknown>)) return true;
227		}
228		return false;
229	}
230	
231	function describeSites(uses: readonly ApplicationPackageUse[]): string {
232		return uses
233			.map((use) => `${use.path}:${String(use.line)} (${use.kind} \`${use.specifier}\`)`)
234			.join(', ');
235	}
236	
237	/**
238	 * Declare, in the application's own manifest, the packages its own source names
239	 * and the manifest does not.
240	 *
241	 * A loader named by an inline chain is a build-time edge and is declared in
242	 * `devDependencies`; a module the application imports is a runtime edge and is
243	 * declared in `dependencies`. A package used both ways is declared once, as a
244	 * runtime edge, because that is the stronger of the two claims.
245	 */
246	export function declareApplicationSourceDependencies(
247		manifest: PackageManifest,
248		uses: readonly ApplicationPackageUse[],
249		cell: AngularTargetCell,
250		eraClosureTypePackages: readonly string[] = [],
251	): ApplicationDependencyDeclarations {
252		const byPackage = new Map<string, ApplicationPackageUse[]>();
253		for (const use of uses) {
254			const group = byPackage.get(use.package) ?? [];
255			group.push(use);
256			byPackage.set(use.package, group);
257		}
258		const typesInEraClosure = new Set(eraClosureTypePackages);
259		const declarations: ApplicationDependencyDeclaration[] = [];
260		const declaredDifferences: string[] = [];
261		const unhandled: string[] = [];
262		const added: Record<'dependencies' | 'devDependencies', Record<string, string>> = {
263			dependencies: {},
264			devDependencies: {},
265		};
266		for (const name of [...byPackage.keys()].sort(compareStrings)) {
267			const group = byPackage.get(name) ?? [];
268			if (declares(manifest, name)) continue;
269			const sites = describeSites(group);
270			const disposition = ecosystemDispositionOf(name, cell);
271			if (disposition !== null && disposition.kind === 'no-successor') {
272				unhandled.push(
273					`${name} is named by this application's own source — ${sites} — and is not declared by ` +
274						`the migrated manifest, because ${cell.id} read the package and found no line of it ` +
275						`to declare: ${disposition.fact} The import site is the application's, so nothing ` +
276						'here can close it: the source asks for a package this cell has no successor for.',
277				);
278				continue;
279			}
280			const range = alignedVersionRange(name, cell);
281			if (range === null) {
282				unhandled.push(
283					`${name} is named by this application's own source — ${sites} — and is declared by ` +
284						`neither the application manifest nor anything the closure is obliged to supply, but ` +
285						`${cell.id} has read no line for it, so the manifest was left as it is rather than ` +
286						'declaring an unverified version',
287				);
288				continue;
289			}
290			const runtime = group.some((use) => use.kind === 'module-import');
291			const field = runtime ? ('dependencies' as const) : ('devDependencies' as const);
292			const reason =
293				`declared because this application's own source names it and no declaration in the ` +
294				`migrated manifest supplies it: ${sites}. Range read for ${cell.id}: ${range}`;
295			added[field][name] = range;
296			declarations.push(Object.freeze({ field, name, range, reason }));
297			declaredDifferences.push(
298				`${field}.${name} was added: the migrated workspace declares a package the era workspace ` +
299					`never named, because the era closure supplied it without either of them saying so. ${reason}`,
300			);
301			const companion = typesCompanionOf(name);
302			const typed = group.some((use) => use.path.endsWith('.ts'));
303			if (!typed || declares(manifest, companion) || !typesInEraClosure.has(companion)) continue;
304			const companionRange = alignedVersionRange(companion, cell);
305			if (companionRange === null) {
306				unhandled.push(
307					`${companion} was carried by the era closure and ${name} is imported from TypeScript ` +
308						`source — ${sites} — so the declaration this capability just wrote resolves at ` +
309						`runtime and does not type; ${cell.id} has read no line for the companion, so it was ` +
310						'not declared',
311				);
312				continue;
313			}
314			const companionReason =
315				`declared beside ${name}: the era closure carried ${companion}, ${name} is imported from ` +
316				`this application's TypeScript source, and a runtime declaration alone would leave those ` +
317				`imports untyped. Range read for ${cell.id}: ${companionRange}`;
318			added.devDependencies[companion] = companionRange;
319			declarations.push(
320				Object.freeze({
321					field: 'devDependencies' as const,
322					name: companion,
323					range: companionRange,
324					reason: companionReason,
325				}),
326			);
327			declaredDifferences.push(
328				`devDependencies.${companion} was added: the migrated workspace declares a type package ` +
329					`the era workspace never named. ${companionReason}`,
330			);
331		}
332		if (declarations.length === 0)
333			return Object.freeze({
334				manifest,
335				declarations: Object.freeze([]),
336				declaredDifferences: Object.freeze([]),
337				unhandled: Object.freeze(unhandled.sort(compareStrings)),
338			});
339		let next: PackageManifest = manifest;
340		for (const field of ['dependencies', 'devDependencies'] as const) {
341			const entries = added[field];
342			if (Object.keys(entries).length === 0) continue;
343			const current = next[field];
344			if (current !== undefined && (typeof current !== 'object' || current === null))
345				throw new Error(`Application source dependency declaration: "${field}" is not an object`);
346			const merged: Record<string, unknown> = {
347				...(current as Record<string, unknown> | undefined),
348				...entries,
349			};
350			const sorted: Record<string, unknown> = {};
351			for (const key of Object.keys(merged).sort(compareStrings)) sorted[key] = merged[key];
352			next = Object.freeze({ ...next, [field]: Object.freeze(sorted) });
353		}
354		return Object.freeze({
355			manifest: next,
356			declarations: Object.freeze(declarations),
357			declaredDifferences: Object.freeze(declaredDifferences.sort(compareStrings)),
358			unhandled: Object.freeze(unhandled.sort(compareStrings)),
359		});
360	}
